class AiPreviewExpiryServiceTest {@Test void expiresLockedTemporaryPreviewAndDeletesContent(){var candidates=mock(AiPreviewExpiryRepository.class);var previews=mock(AiTripPreviewRepository.class);var preview=mock(AiTripPreview.class);var now=LocalDateTime.of(2026,9,12,12,0);when(candidates.findExpiredIds(now)).thenReturn(List.of(9L));when(previews.findByIdForGate(9L)).thenReturn(Optional.of(preview));when(preview.getRetentionStatus()).thenReturn(AiPreviewRetentionStatus.TEMPORARY);when(preview.getExpiresAt()).thenReturn(now);new AiPreviewExpiryService(candidates,previews,Clock.fixed(now.toInstant(ZoneOffset.UTC),ZoneOffset.UTC)).expireDuePreviews();verify(preview).expireContent(now);}}
